contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address caller, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0, "amount must be positive");
        require(address(this).balance >= amount, "insufficient balance");

        uint balBefore = c.balances(caller); if (__ESBMC_reverted()) return;
        uint cEtherBefore = address(c).balance;

        // Deposit from caller: we need the test contract to be msg.sender for c, so we cannot
        // deposit as "caller" directly unless caller == address(this). To keep the rule general
        // and independent of the caller's identity, we deposit as the test contract.
        // The rule then applies to the actual msg.sender (the test contract).
        c.Deposit{value: amount}(); if (__ESBMC_reverted()) return;

        uint balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cEtherAfter = address(c).balance;

        assert(balAfter == balBefore + amount && cEtherAfter == cEtherBefore + amount);
    }

    receive() external payable {}
}

